<script setup lang="ts">
import { computed, onMounted, ref } from "vue";
import { useRoute, useRouter } from "vue-router";
import { CheckCircle2, LoaderCircle } from "lucide-vue-next";
import Logo from "@/components/brand/Logo.vue";
import { ApiError, defaultAuthenticatedPath, hydrateAppState, storeAuth } from "@/lib/api";
import { parentRepository } from "@/data/repositories/parentRepository";
import type { UiInviteDetails } from "@/data/models/parent";

const props = defineProps<{ type: "parent" | "institute" | "educator" }>();
const route = useRoute(); const router = useRouter(); const token = computed(() => String(route.query.token || ""));
const details = ref<UiInviteDetails | null>(null); const name = ref(""); const password = ref(""); const confirmation = ref(""); const loading = ref(true); const saving = ref(false); const error = ref("");
const title = computed(() => props.type === "parent" ? "Activate parent access" : props.type === "educator" ? `Activate ${details.value?.role || "educator"} access` : "Join your institute workspace");
onMounted(async () => { if (!token.value) { error.value = "The invitation token is missing."; loading.value = false; return; } try { details.value = await parentRepository.invite(props.type, token.value); name.value = details.value.name; } catch (reason) { error.value = reason instanceof Error ? reason.message : "This invitation is invalid or expired."; } finally { loading.value = false; } });
async function activate() { if (!details.value?.existingAccount && password.value !== confirmation.value) { error.value = "Passwords do not match."; return; } saving.value = true; error.value = ""; try { const payload = details.value?.existingAccount ? { current_password: password.value } : { name: name.value, password: password.value, password_confirmation: confirmation.value }; const response = props.type === "parent" ? await parentRepository.activateParent(token.value, payload) : props.type === "educator" ? await parentRepository.activateEducator(token.value, payload) : await parentRepository.activateInstitute(token.value, payload); const user = storeAuth(response); await hydrateAppState(); await router.replace(defaultAuthenticatedPath(user)); } catch (reason) { error.value = reason instanceof ApiError ? reason.message : "Unable to activate this invitation."; } finally { saving.value = false; } }
</script>
<template><div class="min-h-screen bg-bg"><div class="border-b border-border bg-bg-card px-6 py-5"><Logo /></div><main class="mx-auto grid min-h-[calc(100vh-78px)] max-w-md place-items-center px-5 py-10"><form class="w-full rounded-2xl border border-border bg-bg-card p-6 shadow-xl" @submit.prevent="activate"><div class="mb-5 grid h-11 w-11 place-items-center rounded-xl bg-mint-light text-mint"><CheckCircle2 :size="21" /></div><h1 class="text-[24px] font-bold text-ink">{{ title }}</h1><p v-if="details" class="mt-2 text-[13px] text-ink3">{{ details.email }} · {{ type === 'parent' ? `Access for ${details.context}` : details.context }}</p><div v-if="loading" class="mt-6 h-32 animate-pulse rounded-xl bg-bg-soft" /><template v-else-if="details"><p v-if="details.existingAccount" class="mt-5 rounded-xl bg-blue-light p-3 text-[12px] text-blue">This email already has an account. Enter its current password to accept the invitation.</p><div class="mt-6 space-y-3"><label v-if="!details.existingAccount" class="block text-[11px] font-semibold">Name<input v-model="name" required class="ops-input" /></label><label class="block text-[11px] font-semibold">{{ details.existingAccount ? 'Current password' : 'Create password' }}<input v-model="password" required minlength="8" type="password" class="ops-input" /></label><label v-if="!details.existingAccount" class="block text-[11px] font-semibold">Confirm password<input v-model="confirmation" required minlength="8" type="password" class="ops-input" /></label></div><button :disabled="saving" class="mt-5 flex w-full items-center justify-center gap-2 rounded-xl bg-blue py-3 text-[13px] font-semibold text-white disabled:opacity-60"><LoaderCircle v-if="saving" :size="15" class="animate-spin" />{{ saving ? 'Activating…' : 'Activate and sign in' }}</button></template><p v-if="error" class="mt-4 rounded-xl bg-pink-light p-3 text-[12px] text-pink">{{ error }}</p></form></main></div></template>
